#include "ArchimedesRuntime.h"
#include "HAL/PlatformProcess.h"
bool FArchimedesRuntime::Load(const FString& LibraryPath,FString& OutError){ Unload(); if(LibraryPath.IsEmpty()){OutError=TEXT("ArchimedesCore library path is empty.");return false;} LibraryHandle=FPlatformProcess::GetDllHandle(*LibraryPath); if(!LibraryHandle){OutError=FString::Printf(TEXT("Unable to load ArchimedesCore: %s"),*LibraryPath);return false;} EvaluateFn=reinterpret_cast<decltype(EvaluateFn)>(FPlatformProcess::GetDllExport(LibraryHandle,TEXT("ArchimedesEvaluateGeodeticInvariants"))); SaintVenantFn=reinterpret_cast<decltype(SaintVenantFn)>(FPlatformProcess::GetDllExport(LibraryHandle,TEXT("ArchimedesSolveSaintVenant1D"))); StatusNameFn=reinterpret_cast<decltype(StatusNameFn)>(FPlatformProcess::GetDllExport(LibraryHandle,TEXT("ArchimedesStatusName"))); if(!EvaluateFn||!SaintVenantFn||!StatusNameFn){OutError=TEXT("ArchimedesCore is missing a required C ABI export.");Unload();return false;} return true; }
void FArchimedesRuntime::Unload(){EvaluateFn=nullptr;SaintVenantFn=nullptr;StatusNameFn=nullptr;if(LibraryHandle){FPlatformProcess::FreeDllHandle(LibraryHandle);LibraryHandle=nullptr;}}
bool FArchimedesRuntime::Evaluate(const ArchimedesSiteInput& Input,FTSMSiteMetrics& OutMetrics,FString& OutError) const {if(!EvaluateFn||!StatusNameFn){OutError=TEXT("ArchimedesCore is not loaded.");return false;} ArchimedesSiteMetrics Metrics{}; const ArchimedesStatus Status=EvaluateFn(&Input,&Metrics); if(Status!=ARCHIMEDES_OK){OutError=UTF8_TO_TCHAR(StatusNameFn(Status));return false;} OutMetrics.BfeFt=Metrics.bfe_ft;OutMetrics.LagFt=Metrics.lag_ft;OutMetrics.SurfaceWaterElevationFt=Metrics.surface_water_elevation_ft;OutMetrics.bInundationActive=Metrics.inundation_active!=0;return true;}
bool FArchimedesRuntime::StepSaintVenant(const ArchimedesSaintVenantConfig& Config,TArray<double>& DepthFt,TArray<double>& VelocityFps,double DeltaSeconds,FString& OutError) const {if(!SaintVenantFn||!StatusNameFn){OutError=TEXT("Archimedes Saint-Venant solver is not loaded.");return false;} if(DepthFt.Num()!=VelocityFps.Num()||DepthFt.Num()<2){OutError=TEXT("Saint-Venant state arrays must have equal length >= 2.");return false;} const ArchimedesStatus Status=SaintVenantFn(&Config,DepthFt.GetData(),VelocityFps.GetData(),DepthFt.Num(),DeltaSeconds); if(Status!=ARCHIMEDES_OK){OutError=UTF8_TO_TCHAR(StatusNameFn(Status));return false;} return true;}